<div class="mx-auto w-full max-w-6xl px-3 py-6 sm:px-4 sm:py-8 lg:px-8"><h1 class="text-3xl font-black sm:text-4xl">Checkout</h1><form method="post" action="/checkout" class="mt-6 grid gap-5 sm:mt-8 lg:grid-cols-2 lg:gap-6"><?php echo csrf_field(); ?><div class="space-y-4 rounded-2xl border bg-white p-4 sm:p-6"><input name="customer_name" value="<?php echo e(auth()->user()->name ?? ''); ?>" required class="w-full rounded-xl border px-4 py-3" placeholder="Full name"><input name="email" type="email" class="w-full rounded-xl border px-4 py-3" placeholder="Email"><input name="phone" value="<?php echo e(auth()->user()->phone ?? ''); ?>" required class="w-full rounded-xl border px-4 py-3" placeholder="Phone"><textarea name="address" required class="min-h-28 w-full rounded-xl border px-4 py-3" placeholder="Address"></textarea><input name="city" required class="w-full rounded-xl border px-4 py-3" placeholder="City"><input name="postal_code" class="w-full rounded-xl border px-4 py-3" placeholder="Postal code"><input name="country" value="Bangladesh" required class="w-full rounded-xl border px-4 py-3" placeholder="Country"><select name="payment_method" class="w-full rounded-xl border px-4 py-3"><option>COD</option><option>Bkash</option><option>Nagad</option><option>Card</option></select><button class="w-full rounded-xl bg-blue-700 px-6 py-3 font-bold text-white transition hover:bg-blue-800">Place Order</button></div><div class="h-fit rounded-2xl border bg-white p-4 sm:p-6"><h2 class="text-xl font-bold">Order Summary</h2><?php ($total=0); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::openLoop(); ?><?php endif; ?><?php $__currentLoopData = $cart; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $i): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::startLoopIteration(); ?><?php endif; ?><?php ($total += $i['price']*$i['qty']); ?><div class="flex gap-3 justify-between border-b py-3 text-sm"><span class="min-w-0 break-words"><?php echo e($i['name']); ?> × <?php echo e($i['qty']); ?></span><span class="shrink-0">৳ <?php echo e(number_format($i['price']*$i['qty'],2)); ?></span></div><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::endLoop(); ?><?php endif; ?><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::closeLoop(); ?><?php endif; ?><div class="mt-5 flex justify-between gap-4 text-xl font-black"><span>Total</span><span>৳ <?php echo e(number_format($total,2)); ?></span></div></div></form></div>
